let r = 16, h = r*Math.sqrt(3)/2;
let occupancy = 4/5;

function setup() {
	createCanvas(h*50, r*30);
	pixelDensity(4);
	strokeWeight(1);
	strokeJoin(ROUND);
	noLoop();
}

function draw() {
	background("#fffbe6");

	stroke("#ffcc4d");
	for (let y = r/12-height*3/2; y < height*2; y += r/6) {
		line(0, y, width, y-tan(PI/6)*width);
		//line(0, y, width, y+tan(PI/6)*width);
	}

	stroke(5);
	let prevCol;
	for (let y = r/6-height*3/2; y < height*2; y += 4*r) {
		let x = width*3/2-h/2;
		let yOffset = 0;
		while (x > -width/2) {
			x -= h;
			yOffset -= r/2;
			let col;
			do {
				col = random(["#f9c84a", "#56a1c4", "#df5f50", "#ef869e"]);
			} while (col == prevCol)
			prevCol = col;
			fill(col);
			if (random() < 1/2) {
				let large = random() < 10/2;
				house(x, y+yOffset, r, h, large);
			} else {
				let large = random() < 1/2;
				if (large) {
					x -= h;
					yOffset += r/2;
				}
				apartment(x, y+yOffset, r, h, large);
			}
			yOffset += r;
		}
	}
}

function house(x, y, r, h, tall) {
	let heightOffset = tall ? r : 0;

	// front facet
	beginShape();
	vertex(x, y-heightOffset);
	vertex(x, y+r);
	vertex(x+h, y+r/2);
	vertex(x+h, y-r/2-heightOffset);
	vertex(x+h/2, y-h/2-heightOffset);
	endShape(CLOSE);

	fill(5);
	// side facet
	beginShape();
	vertex(x, y-heightOffset);
	vertex(x-h, y-r/2-heightOffset);
	vertex(x-h, y+r/2);
	vertex(x, y+r);
	endShape(CLOSE);

	fill("#fffbe6");
	// back roof facet
	beginShape();
	vertex(x+h/2, y-h/2-heightOffset);
	vertex(x+h, y-r/2-heightOffset);
	vertex(x, y-r-heightOffset);
	vertex(x-h/2, y-r/2-h/2-heightOffset);
	endShape(CLOSE);

	// front roof facet
	beginShape();
	vertex(x+h/2, y-h/2-heightOffset);
	vertex(x-h/2, y-r/2-h/2-heightOffset);
	vertex(x-h, y-r/2-heightOffset);
	vertex(x, y-heightOffset);
	endShape(CLOSE);

	let n = tall ? 3 : 1;
	push();
	noStroke();
	for (let j = 0; j < n; j++) {
		fill(random() < occupancy ? "#fffbe6" : 5);
		beginShape();
		vertex(x+h/3, y+r/3-r/6);
		vertex(x+h/3, y+r*2/3-r/6);
		vertex(x+2*h/3, y+r/2-r/6);
		vertex(x+2*h/3, y+r/6-r/6);
		endShape(CLOSE);
		translate(0, -r/2);
	}
	pop();
}

function apartment(x, y, r, h, large, occupied) {
	let xWidthOffset = large ? h : 0;
	let yWidthOffset = large ? r/2 : 0;

	// front facet
	beginShape();
	vertex(x, y-2*r);
	vertex(x, y+r);
	vertex(x+h+xWidthOffset, y+r/2-yWidthOffset);
	vertex(x+h+xWidthOffset, y-r/2-2*r-yWidthOffset);
	endShape(CLOSE);

	fill(5);
	// side facet
	beginShape();
	vertex(x, y-2*r);
	vertex(x-h, y-r/2-2*r);
	vertex(x-h, y+r/2);
	vertex(x, y+r);
	endShape(CLOSE);

	fill("#fffbe6");
	// roof
	beginShape();
	vertex(x, y-2*r);
	vertex(x+h+xWidthOffset, y-r/2-2*r-yWidthOffset);
	vertex(x+xWidthOffset, y-r-2*r-yWidthOffset);
	vertex(x-h, y-r/2-2*r);
	endShape(CLOSE);

	let m = large ? 3 : 1;
	push();
	noStroke();
	for (let i = 0; i < m; i++) {
		push();
		for (let j = 0; j < 5; j++) {
			fill(random() < occupancy ? "#fffbe6" : 5);
			beginShape();
			vertex(x+h/3, y+r/3-r/6);
			vertex(x+h/3, y+r*2/3-r/6);
			vertex(x+2*h/3, y+r/2-r/6);
			vertex(x+2*h/3, y+r/6-r/6);
			endShape(CLOSE);
			translate(0, -r/2);
		}
		pop();
		translate(h/2, -r/4);
	}
	pop();
}

